/api/q7.sql:
SELECT ano, tipo_eleicao, escopo, territorio, vies, cobertura_pct, cargos, vies_por_cargo
FROM mv_q7_territorio
ORDER BY escopo, territorio, ano;

SELECT id_eleicao AS ano, numero_partido, sigla, onda, nota_media, especialistas, vies, origem
FROM vies_partido
ORDER BY id_eleicao, vies NULLS LAST;

